import itertools
header = open('deploy.log').readline().rstrip('\n')
errors = [l.rstrip('\n') for l in open('deploy.log') if l.startswith('ERROR')]
strs = [header]+errors
def overlap(a,b):
    m = min(len(a),len(b))
    for k in range(m,-1,-1):
        if k==0:
            return 0
        if a[-k:]==b[:k]:
            return k
    return 0
for a,b in itertools.permutations(strs,2):
    print(overlap(a,b), a[-5:], '|', b[:5])
